preConditionHook:
// EL: bullRun = CountIF(close[1] > open[1], runBars). CountIF counts bars
// 0..Length-1 INCLUDING the current bar, and its condition is a true SERIES
// whose own offsets shift per counted bar (EL_FEATURES `countif`, VERIFIED) --
// so the shifted condition counts bars 1..runBars, the run BEFORE this bar.
// The counted condition is on PRICES, which have real history back to the
// chart start, so no zero-filled variable mirror is needed.
// The count is an EL numeric variable, kept as a double, and can never exceed
// runBars -- so >= runBars is the source's '= runBars' without a float
// equality. Every comparison is an EL relational.
bullRun = 0.0;
bearRun = 0.0;
for (int i = 1; i <= (int)runBars; ++i) {
    if (el_gt(close[i], open[i])) bullRun += 1;
    if (el_lt(close[i], open[i])) bearRun += 1;
}
